import CsxSelect from "@/components/CommonComponents/SelectFilter.vue";
import CsxFooterButton from "@/components/CsxCompoment/CsxFooterButton.vue";

const DISPLAY_SCREEN_CONFIG_LOCAL_URL =
  "http://localhost:3000/display-screen-config/management-settings/program-settings/display-screen-config/";
const AUTH_TRANSFER_PREFIX = "CSX_DISPLAY_SCREEN_AUTH:";

const encodeDisplayScreenAuthTransfer = payload => {
  const json = JSON.stringify(payload);
  const utf8 = encodeURIComponent(json).replace(/%([0-9A-F]{2})/g, (_, hex) =>
    String.fromCharCode(Number("0x" + hex))
  );

  return btoa(utf8)
    .replace(/\+/g, "-")
    .replace(/\//g, "_")
    .replace(/=+$/g, "");
};

const buildDisplayScreenAuthTransfer = () => {
  const token = get("tok");

  if (!token) {
    return null;
  }

  return encodeDisplayScreenAuthTransfer({
    source: "csx-web",
    issuedAt: Date.now(),
    token,
    userName: get("userName"),
    userInfo: get("userInfo"),
    permission: get("permission") || [],
    locale: get("locale") || "zh-HK"
  });
};

export default {

openDisplayScreenConfig() {
  const encoded = buildDisplayScreenAuthTransfer();
  const child = window.open("about:blank", "_blank");

  if (!child) {
    return;
  }

  if (encoded) {
    child.name = AUTH_TRANSFER_PREFIX + encoded;
  }

  child.location.replace(DISPLAY_SCREEN_CONFIG_LOCAL_URL);
},

