() => {
  const parse = (key) => {
    const raw = localStorage.getItem(key);
    if (!raw) return null;
    try { return JSON.parse(raw); } catch { return raw; }
  };
  const token = parse('tok');
  const userInfo = parse('userInfo');
  const permission = parse('permission');
  return {
    hasToken: typeof token === 'string' && token.length > 10,
    tokenLength: typeof token === 'string' ? token.length : 0,
    userName: parse('userName'),
    clinicCode: userInfo && userInfo.currentClinic && (userInfo.currentClinic.clinicCode || userInfo.currentClinic.code),
    locale: parse('locale'),
    permissionCount: Array.isArray(permission) ? permission.length : 0,
    hasProgramSettings: Array.isArray(permission) && permission.some(p => String(p).startsWith('008014'))
  };
}

